# Test whether demo output is the 4-connected interior enclosed by colored diagonal lines.
from collections import deque
R=C=16
obs2={(0,8),(1,9),(2,10),(3,11),(4,0),(4,12),(5,1),(5,13),(6,2),(6,6),(6,14),(7,3),(7,7),(7,15),(8,4),(8,8),(9,5),(9,9),(10,10),(11,2),(11,11),(12,3),(12,12),(13,4),(13,13),(14,5),(14,14),(15,6)}
seen=set(); q=deque()
for r in range(R):
  for c in (0,C-1):
    if (r,c) not in obs2 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
for c in range(C):
  for r in (0,R-1):
    if (r,c) not in obs2 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
while q:
 r,c=q.popleft()
 for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
  if 0<=nr<R and 0<=nc<C and (nr,nc) not in obs2 and (nr,nc) not in seen:
   seen.add((nr,nc));q.append((nr,nc))
interior={(r,c) for r in range(R) for c in range(C) if (r,c) not in obs2 and (r,c) not in seen}
expected2={(1,7),(1,8),*[(2,c) for c in range(6,10)],*[(3,c) for c in range(5,11)],*[(4,c) for c in range(4,12)],*[(5,c) for c in range(3,13)],*[(6,c) for c in range(3,6)],*[(6,c) for c in range(7,14)],*[(7,c) for c in range(4,7)],*[(7,c) for c in range(8,15)],*[(8,c) for c in range(5,8)],*[(8,c) for c in range(9,15)],*[(9,c) for c in [4,6,7,8]],*[(9,c) for c in range(10,14)],*[(10,c) for c in range(3,10)],*[(10,c) for c in range(11,13)],*[(11,c) for c in range(3,11)],*[(12,c) for c in range(4,10)],*[(13,c) for c in range(5,9)],*[(14,c) for c in range(6,8)]}
print('interior len',len(interior),'expected',len(expected2),'match',interior==expected2)
print('interior rows')
for r in range(16): print(r, ''.join('7' if (r,c) in obs2 else '2' if (r,c) in interior else '.' for c in range(16)))

seen8=set();q=deque()
for r in range(R):
 for c in range(C):
  if (r,c) not in obs2 and (r in (0,R-1) or c in (0,C-1)): seen8.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr in (-1,0,1):
  for dc in (-1,0,1):
   if (dr or dc):
    nr,nc=r+dr,c+dc
    if 0<=nr<R and 0<=nc<C and (nr,nc) not in obs2 and (nr,nc) not in seen8:
     seen8.add((nr,nc));q.append((nr,nc))
interior8={(r,c) for r in range(R) for c in range(C) if (r,c) not in obs2 and (r,c) not in seen8}
print(len(interior8),len(expected2),interior8==expected2)
for r in range(16): print(r, ''.join('7' if (r,c) in obs2 else '2' if (r,c) in interior8 else '.' for c in range(16)))

